// Label's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/label.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The label's own font; empty takes the theme typography of text_style_role (resolved_font). Must be a valid font specification (std::invalid_argument).
template <typename Declaring>
struct LabelFontCapability {
    PropertyCell<std::optional<FontSpec>, LabelFontCapability<Declaring>> font{};

    static void assign(LabelFontCapability& capability, std::optional<FontSpec> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.font), incoming);
        if (!capability.font.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.font));
    }
};

// Horizontal placement of the text: near, center or far.
template <typename Declaring>
struct LabelAlignmentCapability {
    PropertyCell<HorizontalAlignment, LabelAlignmentCapability<Declaring>> alignment{HorizontalAlignment::near};

    static void assign(LabelAlignmentCapability& capability, HorizontalAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.alignment), incoming);
        if (!capability.alignment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.alignment));
    }
};

