// The most lines measured and painted; zero keeps every line. Semantics keep the complete text. At most 4096 (std::out_of_range).
template <typename Declaring>
struct LabelMaximumLinesCapability {
    PropertyCell<std::uint32_t, LabelMaximumLinesCapability<Declaring>> maximum_lines{0U};

    static void assign(LabelMaximumLinesCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.maximum_lines), incoming);
        if (!capability.maximum_lines.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.maximum_lines));
    }
};

