// HorizontalAlignment as a property value; defined beside Label's table.
template <>
struct PropertyValueTraits<HorizontalAlignment> {
    static PropertyType type();
    static BindingValue to_binding(HorizontalAlignment value);
    static HorizontalAlignment from_binding(const BindingValue& value);
};

// VerticalAlignment as a property value; defined beside Label's table.
template <>
struct PropertyValueTraits<VerticalAlignment> {
    static PropertyType type();
    static BindingValue to_binding(VerticalAlignment value);
    static VerticalAlignment from_binding(const BindingValue& value);
};

// TextWrapping as a property value; defined beside Label's table.
template <>
struct PropertyValueTraits<TextWrapping> {
    static PropertyType type();
    static BindingValue to_binding(TextWrapping value);
    static TextWrapping from_binding(const BindingValue& value);
};

// Every Label capability, in the order the declaring class takes them.
template <typename Declaring>
struct LabelCapabilities : public TextCapability<Declaring>,
                           public LabelFontCapability<Declaring>,
                           public LabelAlignmentCapability<Declaring>,
                           public LabelVerticalAlignmentCapability<Declaring>,
                           public LabelTextWrappingCapability<Declaring>,
                           public LabelMaximumLinesCapability<Declaring>,
                           public LabelTextStyleRoleCapability<Declaring>,
                           public LabelLineSpacingCapability<Declaring>,
                           public LabelTextCaseTransformCapability<Declaring>,
                           public LabelUseMnemonicCapability<Declaring> {};

